#nullable enable // autogenerated

using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.decorativeWindSpeed)]
    public class DecorativeWindSpeedBuff : BuffDefinition
    {
        public DecorativeWindSpeedBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(VanillaLevelProps.TARGET_DECORATIVE_WIND_SPEED, NumberOperator.Add, PROP_WIND_SPEED));
        }
        public static void SetWindSpeed(Buff buff, float value) => buff.SetProperty(PROP_WIND_SPEED, value);
        public static float GetWindSpeed(Buff buff) => buff.GetProperty<float>(PROP_WIND_SPEED);
        public static readonly VanillaBuffPropertyMeta<float> PROP_WIND_SPEED = new VanillaBuffPropertyMeta<float>("wind_speed");
    }
}
